import { NextResponse } from 'next/server'
import type { NextRequest } from 'next/server'

// Generate a unique request id, using the Web Crypto API available in the
// Edge runtime, with a crypto-random fallback for older runtimes.
function generateRequestId(): string {
  try {
    if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
      return crypto.randomUUID()
    }
  } catch {
    // fall through to manual generation
  }

  const bytes = new Uint8Array(16)
  if (typeof crypto !== 'undefined' && typeof crypto.getRandomValues === 'function') {
    crypto.getRandomValues(bytes)
  } else {
    for (let i = 0; i < bytes.length; i++) bytes[i] = Math.floor(Math.random() * 256)
  }

  // RFC 4122 version 4 layout
  bytes[6] = (bytes[6] & 0x0f) | 0x40
  bytes[8] = (bytes[8] & 0x3f) | 0x80

  const hex = Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('')
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`
}

export function middleware(request: NextRequest) {
  const pathname = request.nextUrl.pathname

  console.log(`[middleware] request pathname: ${pathname}`)

  // Preserve an incoming request id if present, otherwise generate one.
  const requestId = request.headers.get('x-request-id') || generateRequestId()

  const response = NextResponse.next({
    request: {
      headers: request.headers,
    },
  })

  response.headers.set('X-Request-Id', requestId)

  return response
}

export const config = {
  matcher: [
    /*
     * Match all request paths except for the ones starting with:
     * - _next/static (static files)
     * - _next/image (image optimization files)
     * - favicon.ico, robots.txt (metadata files)
     */
    '/((?!_next/static|_next/image|favicon.ico|robots.txt).*)',
  ],
}
